def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    tokens: list of strings, each either an integer (may be negative) or an operator '+','-','*','/'.
    Returns the integer result, with division truncating toward zero.
    """
    if not tokens:
        return 0
    stack = []
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: int(a / b)  # truncates toward zero
    }
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
