def solve(a, b):
    n, m = len(a), len(b)
    if n < m:
        # ensure that we use space O(min(n,m))
        a, b = b, a
        n, m = m, n
    # now n >= m, we keep dp array of size m+1
    prev = list(range(m+1))
    for i in range(1, n+1):
        cur = [i] + [0]*m
        ai = a[i-1]
        for j in range(1, m+1):
            if ai == b[j-1]:
                cur[j] = prev[j-1]
            else:
                cur[j] = 1 + min(prev[j],    # deletion
                                 cur[j-1],   # insertion
                                 prev[j-1])  # substitution
        prev = cur
    return prev[m]

