    """Evaluate Reverse Polish Notation expression with proper truncating division.
    Supports +, -, *, / where division truncates toward zero.
    """
    if not tokens:
        return 0
    stack = []
    def trunc_div(a, b):
        # Perform integer division truncating toward zero without using float
        if b == 0:
            raise ZeroDivisionError('division by zero')
        neg = (a < 0) ^ (b < 0)
        a_abs, b_abs = abs(a), abs(b)
        res = a_abs // b_abs
        return -res if neg else res
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': trunc_div,
