def solve(a: str, b: str) -> int:
    # Space-optimized DP for edit distance (Levenshtein)
    # Ensure the shorter string is b to use O(len(b)) space
    if len(a) < len(b):
        a, b = b, a
    # now len(a) >= len(b)
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        current = [i] + [0] * len(b)
        for j, cb in enumerate(b, start=1):
            if ca == cb:
                current[j] = previous[j-1]
            else:
                current[j] = 1 + min(previous[j],    # deletion
                                       current[j-1],  # insertion
                                       previous[j-1]) # substitution
        previous = current
    return previous[-1]

